        0 => KeyCode::KEY_A,
        1 => KeyCode::KEY_S,
        2 => KeyCode::KEY_D,
        3 => KeyCode::KEY_F,
        4 => KeyCode::KEY_H,
        5 => KeyCode::KEY_G,
