pub struct WindowsInputInjector {
    target: TargetDisplay,
    desktop: VirtualDesktop,
    modifiers: Modifiers,
}

impl WindowsInputInjector {
    pub fn new(target: Option<TargetDisplay>) -> io::Result<Self> {
        let desktop = current_virtual_desktop()?;
        let target = target.unwrap_or_else(|| TargetDisplay::from_virtual_desktop(desktop));
        if target.width == 0 || target.height == 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "target display dimensions must be non-zero",
            ));
        }
        Ok(Self {
            target,
            desktop,
            modifiers: Modifiers::empty(),
        })
    }

    pub fn update_target(&mut self, target: TargetDisplay) {
        self.target = target;
    }

    pub fn refresh_virtual_desktop(&mut self) -> io::Result<()> {
        self.desktop = current_virtual_desktop()?;
        Ok(())
    }

    pub fn move_relative(&mut self, dx: i32, dy: i32) -> io::Result<()> {
        send_inputs(&[mouse_input(dx, dy, 0, MOUSEEVENTF_MOVE)])
    }

    pub fn inject(&mut self, event: &InputEvent) -> io::Result<()> {
        if !event.x.is_finite()
            || !event.y.is_finite()
            || !event.scroll_dx.is_finite()
            || !event.scroll_dy.is_finite()
        {
            return Ok(());
        }
        match event.event_type {
            InputEventType::MouseMove
            | InputEventType::LeftMouseDragged
            | InputEventType::RightMouseDragged
            | InputEventType::LeftMouseDown
            | InputEventType::LeftMouseUp
            | InputEventType::RightMouseDown
            | InputEventType::RightMouseUp => {
                let (x, y) = normalize_absolute_pointer(event.x, event.y, self.target, self.desktop);
                let mut flags = MOUSEEVENTF_MOVE | MOUSEEVENTF_ABSOLUTE | MOUSEEVENTF_VIRTUALDESK;
                flags |= match event.event_type {
                    InputEventType::LeftMouseDown => MOUSEEVENTF_LEFTDOWN,
                    InputEventType::LeftMouseUp => MOUSEEVENTF_LEFTUP,
                    InputEventType::RightMouseDown => MOUSEEVENTF_RIGHTDOWN,
                    InputEventType::RightMouseUp => MOUSEEVENTF_RIGHTUP,
                    _ => MOUSE_EVENT_FLAGS(0),
                };
                send_inputs(&[mouse_input(x, y, 0, flags)])
            }
            InputEventType::ScrollWheel => {
                let mut inputs = Vec::with_capacity(2);
                let vertical = scroll_units(event.scroll_dy);
                if vertical != 0 {
                    inputs.push(mouse_input(0, 0, vertical as u32, MOUSEEVENTF_WHEEL));
                }
                let horizontal = scroll_units(event.scroll_dx);
                if horizontal != 0 {
                    inputs.push(mouse_input(0, 0, horizontal as u32, MOUSEEVENTF_HWHEEL));
                }
                send_inputs(&inputs)
            }
            InputEventType::KeyDown | InputEventType::KeyUp => {
                let mut inputs = modifier_inputs(self.modifiers, event.modifiers);
                self.modifiers = event.modifiers;
                if let Some(vk) = macos_keycode_to_vk(event.key_code) {
                    inputs.push(key_input(vk, event.event_type == InputEventType::KeyUp));
                }
                send_inputs(&inputs)
            }
            InputEventType::FlagsChanged => {
                let inputs = modifier_inputs(self.modifiers, event.modifiers);
                self.modifiers = event.modifiers;
                send_inputs(&inputs)
            }
        }
    }
}

impl Drop for WindowsInputInjector {
    fn drop(&mut self) {
        let inputs = modifier_inputs(self.modifiers, Modifiers::empty());
        let _ = send_inputs(&inputs);
    }
}

fn current_virtual_desktop() -> io::Result<VirtualDesktop> {
    let x = unsafe { GetSystemMetrics(SM_XVIRTUALSCREEN) };
    let y = unsafe { GetSystemMetrics(SM_YVIRTUALSCREEN) };
    let width = unsafe { GetSystemMetrics(SM_CXVIRTUALSCREEN) };
    let height = unsafe { GetSystemMetrics(SM_CYVIRTUALSCREEN) };
    if width <= 0 || height <= 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(VirtualDesktop {
        x,
        y,
        width: width as u32,
        height: height as u32,
    })
}

fn modifier_inputs(previous: Modifiers, current: Modifiers) -> Vec<INPUT> {
    [
        (Modifiers::SHIFT, VK_LSHIFT.0),
        (Modifiers::CONTROL, VK_LCONTROL.0),
        (Modifiers::OPTION, VK_LMENU.0),
        (Modifiers::COMMAND, VK_LWIN.0),
    ]
    .into_iter()
    .filter_map(|(modifier, vk)| {
        let was_down = previous.contains(modifier);
        let is_down = current.contains(modifier);
        (was_down != is_down).then(|| key_input(vk, !is_down))
    })
    .collect()
}

fn is_extended_key(vk: u16) -> bool {
    matches!(
        vk,
        0x21..=0x28 | 0x2D | 0x2E | 0x5B | 0x5C | 0x6F | 0xA3 | 0xA5
    )
}

fn key_input(vk: u16, key_up: bool) -> INPUT {
    let mut flags = KEYBD_EVENT_FLAGS(0);
    if key_up {
        flags |= KEYEVENTF_KEYUP;
    }
    if is_extended_key(vk) {
        flags |= KEYEVENTF_EXTENDEDKEY;
    }
    INPUT {
        r#type: INPUT_KEYBOARD,
        Anonymous: INPUT_0 {
            ki: KEYBDINPUT {
                wVk: VIRTUAL_KEY(vk),
                wScan: 0,
                dwFlags: flags,
                time: 0,
                dwExtraInfo: 0,
            },
        },
    }
}

fn mouse_input(dx: i32, dy: i32, data: u32, flags: MOUSE_EVENT_FLAGS) -> INPUT {
    INPUT {
        r#type: INPUT_MOUSE,
        Anonymous: INPUT_0 {
            mi: MOUSEINPUT {
                dx,
                dy,
                mouseData: data,
                dwFlags: flags,
                time: 0,
                dwExtraInfo: 0,
            },
        },
    }
}

fn scroll_units(delta: f32) -> i32 {
    (delta * WHEEL_DELTA)
        .round()
        .clamp(i32::MIN as f32, i32::MAX as f32) as i32
}

fn send_inputs(inputs: &[INPUT]) -> io::Result<()> {
    if inputs.is_empty() {
        return Ok(());
    }
    let sent = unsafe { SendInput(inputs, size_of::<INPUT>() as i32) };
    if sent == inputs.len() as u32 {
        Ok(())
    } else {
        Err(io::Error::last_os_error())
    }
}

//! Win32 text clipboard synchronization with sequence-number echo suppression.
//!
//! Windows' `GetClipboardSequenceNumber` is the direct analogue of
//! `NSPasteboard.changeCount`: after applying remote text, the resulting number
//! is recorded and the matching poll is suppressed. A deterministic content
//! hash adds the same content-level dedup used by the Swift host.
//!
//! Sensitive clipboard entries have no universal Windows marker. Before text is
//! read this backend checks Microsoft's registered exclusion formats, including
//! `ExcludeClipboardContentFromMonitorProcessing` (the practical equivalent of
//! `CFSTR_EXCLUDED_FROM_PROCESS_HISTORY`), `CanIncludeInClipboardHistory`, and
//! `CanUploadToCloudClipboard`. Remote writes publish the exclusion format so
//! synchronized text is not persisted by Clipboard History or cloud roaming.
//!
//! CI validates the bindings and pure state-machine tests. Runtime QA still
//! requires a real Windows desktop because the clipboard is a session-global,
//! contended resource.

use clipboard_win::{
    formats::{RawData, Unicode, CF_UNICODETEXT},
    raw, Clipboard, Format, Getter, Setter,
};
use erd_proto::control::MAX_CLIPBOARD_TEXT_BYTES;
use thiserror::Error;

const FORMAT_EXCLUDE_MONITOR: &str = "ExcludeClipboardContentFromMonitorProcessing";
const FORMAT_INCLUDE_HISTORY: &str = "CanIncludeInClipboardHistory";
const FORMAT_UPLOAD_CLOUD: &str = "CanUploadToCloudClipboard";
const FALSE_DWORD: [u8; 4] = 0_u32.to_le_bytes();
const TRUE_DWORD: [u8; 4] = 1_u32.to_le_bytes();

#[derive(Debug, Error)]
pub enum ClipboardError {
    #[error("Win32 clipboard operation failed: {0}")]
    Win32(String),
    #[error("clipboard text exceeds the 4 KiB protocol limit")]
    TooLarge,
}

fn win32<T>(result: clipboard_win::SysResult<T>) -> Result<T, ClipboardError> {
    result.map_err(|error| ClipboardError::Win32(error.to_string()))
}

/// Stable FNV-1a hash used for cross-platform deterministic tests and dedup.
pub fn content_hash(text: &str) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325_u64;
    for byte in text.as_bytes() {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ClipboardEchoSuppressor {
    last_sequence: Option<u32>,
    last_written_sequence: Option<u32>,
    last_hash: Option<u64>,
}

impl ClipboardEchoSuppressor {
    pub const fn new() -> Self {
        Self {
            last_sequence: None,
            last_written_sequence: None,
            last_hash: None,
        }
    }

    pub fn start(&mut self, sequence: u32) {
        self.last_sequence = Some(sequence);
        self.last_written_sequence = None;
        self.last_hash = None;
    }

    pub fn record_remote_write(&mut self, sequence: u32, text: &str) {
        self.last_sequence = Some(sequence);
        self.last_written_sequence = Some(sequence);
        self.last_hash = Some(content_hash(text));
    }

    /// Returns whether the sequence should be read. Echo and unchanged polls
    /// still advance `last_sequence`, exactly like the Swift monitor.
    pub fn observe_sequence(&mut self, sequence: u32) -> bool {
        if self.last_sequence == Some(sequence) {
            return false;
        }
        self.last_sequence = Some(sequence);
        self.last_written_sequence != Some(sequence)
    }

    /// Returns true only for a new content value that should cross the wire.
    pub fn observe_text(&mut self, text: &str) -> bool {
        let hash = content_hash(text);
        if self.last_hash == Some(hash) {
            return false;
        }
        self.last_hash = Some(hash);
        true
    }
}

impl Default for ClipboardEchoSuppressor {
    fn default() -> Self {
        Self::new()
    }
}

#[derive(Debug, Clone, Copy)]
struct SensitiveFormats {
    exclude_monitor: Option<u32>,
    include_history: Option<u32>,
    upload_cloud: Option<u32>,
}

impl SensitiveFormats {
    fn register() -> Self {
        Self {
            exclude_monitor: raw::register_format(FORMAT_EXCLUDE_MONITOR).map(|id| id.get()),
            include_history: raw::register_format(FORMAT_INCLUDE_HISTORY).map(|id| id.get()),
            upload_cloud: raw::register_format(FORMAT_UPLOAD_CLOUD).map(|id| id.get()),
        }
    }

    fn selection_is_sensitive(self) -> bool {
        self.exclude_monitor.is_some_and(raw::is_format_avail)
            || self
                .include_history
                .is_some_and(|format| format_is_false(format))
            || self
                .upload_cloud
                .is_some_and(|format| format_is_false(format))
    }

    fn publish_remote_exclusions(self) -> Result<(), ClipboardError> {
        if let Some(format) = self.exclude_monitor {
            win32(RawData(format).write_clipboard(&TRUE_DWORD))?;
        }
        if let Some(format) = self.include_history {
            win32(RawData(format).write_clipboard(&FALSE_DWORD))?;
        }
        if let Some(format) = self.upload_cloud {
            win32(RawData(format).write_clipboard(&FALSE_DWORD))?;
        }
        Ok(())
    }
}

pub struct WindowsClipboard {
    suppressor: ClipboardEchoSuppressor,
    formats: SensitiveFormats,
}

impl WindowsClipboard {
    pub fn new() -> Self {
        let mut suppressor = ClipboardEchoSuppressor::new();
        if let Some(sequence) = sequence_number() {
            suppressor.start(sequence);
        }
        Self {
            suppressor,
            formats: SensitiveFormats::register(),
        }
    }

    /// Poll once. `Ok(None)` means unchanged, echo-suppressed, concealed, empty,
    /// unavailable, or over the protocol's 4 KiB UTF-8 cap.
    pub fn poll(&mut self) -> Result<Option<String>, ClipboardError> {
        let Some(sequence) = sequence_number() else {
            return Ok(None);
        };
        if !self.suppressor.observe_sequence(sequence) {
            return Ok(None);
        }

        let clipboard = win32(Clipboard::new_attempts(10))?;
        if self.formats.selection_is_sensitive() || !Unicode.is_format_avail() {
            drop(clipboard);
            return Ok(None);
        }

        // Avoid allocating an arbitrarily large UTF-16 selection. Four KiB of
        // UTF-8 cannot require more than 8 KiB plus the UTF-16 terminator.
        let max_utf16_storage = MAX_CLIPBOARD_TEXT_BYTES * 2 + 2;
        if raw::size(CF_UNICODETEXT)
            .is_some_and(|bytes| bytes.get() > max_utf16_storage)
        {
            drop(clipboard);
            return Ok(None);
        }

        let mut text = String::new();
        win32(Unicode.read_clipboard(&mut text))?;
        drop(clipboard);
        if text.is_empty() || text.len() > MAX_CLIPBOARD_TEXT_BYTES {
            return Ok(None);
        }
        Ok(self.suppressor.observe_text(&text).then_some(text))
    }

    pub fn apply_remote_text(&mut self, text: &str) -> Result<(), ClipboardError> {
        if text.len() > MAX_CLIPBOARD_TEXT_BYTES {
            return Err(ClipboardError::TooLarge);
        }
        let clipboard = win32(Clipboard::new_attempts(10))?;
        win32(raw::empty())?;
        // `Unicode::write_clipboard` normally clears first. We already cleared
        // once so the text and exclusion formats remain in one clipboard entry.
        win32(raw::set_string_with(text, clipboard_win::options::NoClear))?;
        self.formats.publish_remote_exclusions()?;
        let sequence = sequence_number().unwrap_or_default();
        drop(clipboard);
        self.suppressor.record_remote_write(sequence, text);
        Ok(())
    }
}

impl Default for WindowsClipboard {
    fn default() -> Self {
        Self::new()
    }
}

fn sequence_number() -> Option<u32> {
    raw::seq_num().map(|number| number.get())
}

fn format_is_false(format: u32) -> bool {
    if !raw::is_format_avail(format) {
        return false;
    }
    let mut bytes = Vec::new();
    if RawData(format).read_clipboard(&mut bytes).is_err() {
        return true;
    }
    if bytes.len() < 4 {
        return true;
    }
    u32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]]) == 0
}

