use std::sync::Mutex;
use std::time::Instant;

use erd_proto::{map_to_host_pixels, InputEvent, InputEventType, Modifiers};
use thiserror::Error;

const MAX_EVENTS_PER_SECOND: f64 = 200.0;
const BURST_CAPACITY: f64 = 400.0;

#[derive(Debug, Error)]
pub enum InputError {
    #[error("Accessibility access is not granted")]
    PermissionDenied,
    #[error("invalid input coordinates")]
    InvalidCoordinates,
    #[error("CoreGraphics could not create the event")]
    EventCreation,
    #[error("input rate limit exceeded")]
    RateLimited,
    #[error("input injection is available only on macOS")]
    Unsupported,
}

struct RateLimit {
    tokens: f64,
    last_refill: Instant,
}

pub struct InputInjector {
    host_width: f32,
    host_height: f32,
    rate_limit: Mutex<RateLimit>,
}

impl InputInjector {
    pub fn new(host_width: f32, host_height: f32) -> Self {
        Self {
            host_width,
            host_height,
            rate_limit: Mutex::new(RateLimit {
                tokens: BURST_CAPACITY,
                last_refill: Instant::now(),
            }),
        }
    }

    pub fn map_coordinates(&self, event: &InputEvent) -> Result<(f32, f32), InputError> {
        if !event.x.is_finite() || !event.y.is_finite() {
            return Err(InputError::InvalidCoordinates);
        }
        Ok(map_to_host_pixels(
            event.x.clamp(0.0, 1.0),
            event.y.clamp(0.0, 1.0),
            self.host_width,
            self.host_height,
        ))
    }

    fn allow_event(&self) -> bool {
        let mut state = self.rate_limit.lock().expect("input rate limiter poisoned");
        let now = Instant::now();
        state.tokens = (state.tokens
            + now.duration_since(state.last_refill).as_secs_f64() * MAX_EVENTS_PER_SECOND)
            .min(BURST_CAPACITY);
        state.last_refill = now;
        if state.tokens < 1.0 {
            return false;
        }
        state.tokens -= 1.0;
        true
    }

    #[cfg(target_os = "macos")]
    pub fn inject(&self, event: &InputEvent) -> Result<(), InputError> {
        use core_graphics::event::{
            CGEvent, CGEventFlags, CGEventTapLocation, CGEventType, CGMouseButton,
            ScrollEventUnit,
        };
        use core_graphics::event_source::{CGEventSource, CGEventSourceStateID};
        use core_graphics::geometry::CGPoint;

        if !accessibility_is_trusted() {
            return Err(InputError::PermissionDenied);
        }
        if !self.allow_event() {
            return Err(InputError::RateLimited);
        }
        let (x, y) = self.map_coordinates(event)?;
        let point = CGPoint::new(x as f64, y as f64);
        let flags = cg_flags(event.modifiers);
        let source = || {
            CGEventSource::new(CGEventSourceStateID::HIDSystemState)
                .map_err(|_| InputError::EventCreation)
        };

        let cg_event = match event.event_type {
            InputEventType::MouseMove => CGEvent::new_mouse_event(
                source()?,
                CGEventType::MouseMoved,
                point,
                CGMouseButton::Left,
            ),
            InputEventType::LeftMouseDragged => CGEvent::new_mouse_event(
                source()?,
                CGEventType::LeftMouseDragged,
                point,
                CGMouseButton::Left,
            ),
            InputEventType::RightMouseDragged => CGEvent::new_mouse_event(
                source()?,
                CGEventType::RightMouseDragged,
                point,
                CGMouseButton::Right,
            ),
            InputEventType::LeftMouseDown => CGEvent::new_mouse_event(
                source()?,
                CGEventType::LeftMouseDown,
                point,
                CGMouseButton::Left,
            ),
            InputEventType::LeftMouseUp => CGEvent::new_mouse_event(
                source()?,
                CGEventType::LeftMouseUp,
                point,
                CGMouseButton::Left,
            ),
            InputEventType::RightMouseDown => CGEvent::new_mouse_event(
                source()?,
                CGEventType::RightMouseDown,
                point,
                CGMouseButton::Right,
            ),
            InputEventType::RightMouseUp => CGEvent::new_mouse_event(
                source()?,
                CGEventType::RightMouseUp,
                point,
                CGMouseButton::Right,
            ),
            InputEventType::ScrollWheel => CGEvent::new_scroll_event(
                source()?,
                ScrollEventUnit::PIXEL,
                2,
                event.scroll_dy.round() as i32,
                event.scroll_dx.round() as i32,
                0,
            ),
            InputEventType::KeyDown => {
                CGEvent::new_keyboard_event(source()?, event.key_code, true)
            }
            InputEventType::KeyUp => {
                CGEvent::new_keyboard_event(source()?, event.key_code, false)
            }
            InputEventType::FlagsChanged => {
                CGEvent::new_keyboard_event(source()?, event.key_code, true)
            }
        }
        .map_err(|_| InputError::EventCreation)?;
        cg_event.set_flags(flags);
        cg_event.post(CGEventTapLocation::HID);
        Ok(())
    }

    #[cfg(not(target_os = "macos"))]
    pub fn inject(&self, _event: &InputEvent) -> Result<(), InputError> {
        Err(InputError::Unsupported)
    }
}

#[cfg(target_os = "macos")]
fn cg_flags(modifiers: Modifiers) -> core_graphics::event::CGEventFlags {
    use core_graphics::event::CGEventFlags;
    let mut flags = CGEventFlags::empty();
    if modifiers.contains(Modifiers::SHIFT) {
        flags.insert(CGEventFlags::CGEventFlagShift);
    }
    if modifiers.contains(Modifiers::CONTROL) {
        flags.insert(CGEventFlags::CGEventFlagControl);
    }
    if modifiers.contains(Modifiers::OPTION) {
        flags.insert(CGEventFlags::CGEventFlagAlternate);
    }
    if modifiers.contains(Modifiers::COMMAND) {
        flags.insert(CGEventFlags::CGEventFlagCommand);
    }
    if modifiers.contains(Modifiers::CAPS_LOCK) {
        flags.insert(CGEventFlags::CGEventFlagAlphaShift);
    }
    flags
}

#[cfg(target_os = "macos")]
pub fn accessibility_is_trusted() -> bool {
    extern "C" {
        fn AXIsProcessTrusted() -> u8;
    }
    unsafe { AXIsProcessTrusted() != 0 }
}

#[cfg(not(target_os = "macos"))]
pub fn accessibility_is_trusted() -> bool {
    false
}

#[cfg(target_os = "macos")]
pub fn request_accessibility() -> bool {
    use core_foundation::base::TCFType;
    use core_foundation::boolean::CFBoolean;
    use core_foundation::dictionary::CFDictionary;
    use core_foundation::string::CFString;

    extern "C" {
        static kAXTrustedCheckOptionPrompt: core_foundation::string::CFStringRef;
        fn AXIsProcessTrustedWithOptions(
            options: core_foundation::dictionary::CFDictionaryRef,
        ) -> u8;
    }

    unsafe {
        let key = CFString::wrap_under_get_rule(kAXTrustedCheckOptionPrompt);
        let options = CFDictionary::from_CFType_pairs(&[(key, CFBoolean::true_value())]);
        AXIsProcessTrustedWithOptions(options.as_concrete_TypeRef()) != 0
    }
}

#[cfg(not(target_os = "macos"))]
pub fn request_accessibility() -> bool {
    false
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn normalized_coordinates_map_to_absolute_host_pixels() {
        let injector = InputInjector::new(1920.0, 1080.0);
        let event = InputEvent {
            event_type: InputEventType::MouseMove,
            x: 0.25,
            y: 0.75,
            key_code: 0,
            modifiers: Modifiers::empty(),
            scroll_dx: 0.0,
            scroll_dy: 0.0,
        };
        assert_eq!(injector.map_coordinates(&event).unwrap(), (480.0, 810.0));
    }

    #[test]
    fn coordinates_are_clamped_and_nan_is_rejected() {
        let injector = InputInjector::new(100.0, 50.0);
        let mut event = InputEvent {
            event_type: InputEventType::MouseMove,
            x: -1.0,
            y: 2.0,
            key_code: 0,
            modifiers: Modifiers::empty(),
            scroll_dx: 0.0,
            scroll_dy: 0.0,
        };
        assert_eq!(injector.map_coordinates(&event).unwrap(), (0.0, 50.0));
        event.x = f32::NAN;
        assert!(matches!(
            injector.map_coordinates(&event),
            Err(InputError::InvalidCoordinates)
        ));
    }
}

//! Windows host pure logic kept target-independent for unit tests.

use erd_proto::input::Modifiers;

const ABSOLUTE_AXIS_MAX: f64 = 65_535.0;

/// Windows virtual desktop bounds in physical pixels.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct VirtualDesktop {
    pub x: i32,
    pub y: i32,
    pub width: u32,
    pub height: u32,
}

/// Target display bounds within the virtual desktop.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TargetDisplay {
    pub x: i32,
    pub y: i32,
    pub width: u32,
    pub height: u32,
}

impl TargetDisplay {
    pub fn from_virtual_desktop(desktop: VirtualDesktop) -> Self {
        Self {
            x: desktop.x,
            y: desktop.y,
            width: desktop.width,
            height: desktop.height,
        }
    }
}

/// Maps normalized protocol coordinates into the Windows absolute-input range.
pub fn normalize_absolute_pointer(
    normalized_x: f32,
    normalized_y: f32,
    target: TargetDisplay,
    desktop: VirtualDesktop,
) -> (i32, i32) {
    if target.width == 0 || target.height == 0 || desktop.width <= 1 || desktop.height <= 1 {
        return (0, 0);
    }
    let local_x = finite_unit(normalized_x) * target.width.saturating_sub(1) as f64;
    let local_y = finite_unit(normalized_y) * target.height.saturating_sub(1) as f64;
    let desktop_x = (target.x as f64 + local_x - desktop.x as f64)
        .clamp(0.0, desktop.width.saturating_sub(1) as f64);
    let desktop_y = (target.y as f64 + local_y - desktop.y as f64)
        .clamp(0.0, desktop.height.saturating_sub(1) as f64);
    (
        (desktop_x * ABSOLUTE_AXIS_MAX / desktop.width.saturating_sub(1) as f64).round() as i32,
        (desktop_y * ABSOLUTE_AXIS_MAX / desktop.height.saturating_sub(1) as f64).round() as i32,
    )
}

fn finite_unit(value: f32) -> f64 {
    if value.is_finite() {
        value.clamp(0.0, 1.0) as f64
    } else {
        0.0
    }
}

/// Convert a Windows VK to the protocol's macOS physical-key code.
pub fn vk_to_macos_keycode(vk: u16) -> Option<u16> {
    KEY_MAP
        .iter()
        .find_map(|&(macos, windows)| (windows == vk).then_some(macos))
}

/// Convert a protocol/macOS physical-key code to a Windows VK.
pub fn macos_keycode_to_vk(key_code: u16) -> Option<u16> {
    KEY_MAP
        .iter()
        .find_map(|&(macos, windows)| (macos == key_code).then_some(windows))
}

/// Maps v3 modifier bits to the left-side Win32 VKs used by the injector.
pub fn modifier_vks(modifiers: Modifiers) -> Vec<u16> {
    [
        (Modifiers::SHIFT, 0xA0),
        (Modifiers::CONTROL, 0xA2),
        (Modifiers::OPTION, 0xA4),
        (Modifiers::COMMAND, 0x5B),
        (Modifiers::CAPS_LOCK, 0x14),
    ]
    .into_iter()
    .filter_map(|(modifier, vk)| modifiers.contains(modifier).then_some(vk))
    .collect()
}

/// Stable FNV-1a clipboard hash used for content-level dedup.
pub fn clipboard_content_hash(text: &str) -> u64 {
    let mut hash = 0xcbf2_9ce4_8422_2325_u64;
    for byte in text.as_bytes() {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x0000_0100_0000_01b3);
    }
    hash
}

#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct ClipboardEchoSuppressor {
    last_sequence: Option<u32>,
    last_written_sequence: Option<u32>,
    last_hash: Option<u64>,
}

impl ClipboardEchoSuppressor {
    pub fn start(&mut self, sequence: u32) {
        self.last_sequence = Some(sequence);
        self.last_written_sequence = None;
        self.last_hash = None;
    }

    pub fn record_remote_write(&mut self, sequence: u32, text: &str) {
        self.last_sequence = Some(sequence);
        self.last_written_sequence = Some(sequence);
        self.last_hash = Some(clipboard_content_hash(text));
    }

    pub fn observe_sequence(&mut self, sequence: u32) -> bool {
        if self.last_sequence == Some(sequence) {
            return false;
        }
        self.last_sequence = Some(sequence);
        self.last_written_sequence != Some(sequence)
    }

    pub fn observe_text(&mut self, text: &str) -> bool {
        let hash = clipboard_content_hash(text);
        if self.last_hash == Some(hash) {
            return false;
        }
        self.last_hash = Some(hash);
        true
    }
}

