/// Reads complete stereo sample frames into `output`.
pub fn read_interleaved_f32(&mut self, output: &mut [f32]) -> Result<usize, AudioError> {
    if output.len() < CHANNELS as usize {
        return Ok(0);
    }
    let byte_capacity = output.len() * BYTES_PER_SAMPLE;
    // SAFETY: f32 is plain data, the byte slice has the same allocation and
    // remains borrowed for the duration of the read.
    let bytes = unsafe {
        std::slice::from_raw_parts_mut(output.as_mut_ptr().cast::<u8>(), byte_capacity)
    };
    let read = self.stdout.read(bytes)?;
    let complete_bytes = read - (read % BYTES_PER_SAMPLE_FRAME);
    Ok(complete_bytes / BYTES_PER_SAMPLE)
}

